<?php
require_once __DIR__ . '/../Config/koneksi.php';require_once __DIR__ . '/../Config/auth.php';madin_role_required('admin');require_once __DIR__.'/_layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){madin_csrf_check();$id=(int)($_POST['id_pengguna']??0);$status=(string)($_POST['status_akun']??'');if($id===(int)$_SESSION['id_pengguna'])$error='Status akun admin yang sedang digunakan tidak dapat diubah dari halaman ini.';elseif($id<1||!in_array($status,['aktif','nonaktif'],true))$error='Data perubahan tidak valid.';else{$stmt=mysqli_prepare($conn,'UPDATE pengguna SET status_akun=? WHERE id_pengguna=? AND peran="pelanggan"');mysqli_stmt_bind_param($stmt,'si',$status,$id);$ok=mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);header('Location: pengguna.php?msg='.rawurlencode($ok?'Status akun pelanggan diperbarui.':'Gagal memperbarui akun.'));exit;}}
$q=trim((string)($_GET['q']??''));$search='%'.$q.'%';$stmt=mysqli_prepare($conn,"SELECT id_pengguna,nama,email,telepon,status_akun,dibuat_pada FROM pengguna WHERE peran='pelanggan' AND (nama LIKE ? OR email LIKE ? OR telepon LIKE ?) ORDER BY dibuat_pada DESC LIMIT 300");mysqli_stmt_bind_param($stmt,'sss',$search,$search,$search);mysqli_stmt_execute($stmt);$users=mysqli_stmt_get_result($stmt);$count=mysqli_query($conn,"SELECT COUNT(*) total FROM pengguna WHERE peran='pelanggan'");$total=(int)(mysqli_fetch_assoc($count)['total']??0);madin_admin_header('Manajemen Pengguna','pengguna');if($error):?><div class="notice error"><?=madin_e($error)?></div><?php endif;?><div class="admin-grid"><div class="stat-card"><div class="stat-label">Total akun pelanggan</div><div class="stat-value"><?=$total?></div></div></div><div class="admin-card"><h2>Daftar pelanggan</h2><form class="filter-row" method="get"><input name="q" placeholder="Cari nama, email, telepon" value="<?=madin_e($q)?>"><button class="btn">Cari</button><a class="btn secondary" href="pengguna.php">Reset</a></form><table class="admin-table"><thead><tr><th>Nama</th><th>Email</th><th>Telepon</th><th>Status</th><th>Bergabung</th><th>Aksi</th></tr></thead><tbody><?php if($users&&mysqli_num_rows($users)):while($u=mysqli_fetch_assoc($users)):?><tr><td><?=madin_e($u['nama'])?></td><td><?=madin_e($u['email'])?></td><td><?=madin_e($u['telepon']??'—')?></td><td><span class="status-pill <?=$u['status_akun']==='aktif'?'ok':'bad'?>"><?=madin_e(madin_status_label($u['status_akun']))?></span></td><td><?=madin_e(date('d/m/Y',strtotime($u['dibuat_pada'])))?></td><td><form method="post" onsubmit="return confirm('Ubah status akun pelanggan ini?')"><input type="hidden" name="csrf_token" value="<?=madin_e(madin_csrf_token())?>"><input type="hidden" name="id_pengguna" value="<?=$u['id_pengguna']?>"><input type="hidden" name="status_akun" value="<?=$u['status_akun']==='aktif'?'nonaktif':'aktif'?>"><button class="btn-small <?=$u['status_akun']==='aktif'?'danger':'secondary'?>"><?=$u['status_akun']==='aktif'?'Nonaktifkan':'Aktifkan'?></button></form></td></tr><?php endwhile;else:?><tr><td colspan="6" class="empty-state">Pengguna tidak ditemukan.</td></tr><?php endif;?></tbody></table></div><?php mysqli_stmt_close($stmt);madin_admin_footer();?>
